Description: This Terraform configuration provisions an AWS Lightsail managed relational database. It creates a MySQL Lightsail database instance in a valid AWS region and availability zone, with defaults for database name, username, password, blueprint, and bundle size. The database is configured to be publicly accessible for easy connectivity and includes outputs for the database endpoint and port.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Lightsail managed database will be created."
  type        = string
  default     = "us-east-1"
}

variable "availability_zone" {
  description = "Availability zone for the Lightsail database."
  type        = string
  default     = "us-east-1a"
}

variable "database_name" {
  description = "The Lightsail managed database resource name."
  type        = string
  default     = "lightsail-managed-db"
}

